//! Optional Parts organize canonical chapters through a checked planning draft.
//! The Part-list order never changes chapter or scene reading positions.
use super::*;
use novel_storage::{Chapter,ChapterPart,ManuscriptPart,ManuscriptParts,ManuscriptPartsSnapshot};

fn remove_part(model:&mut ManuscriptParts,id:&str)->Result<(),String>{let count=model.parts.iter().filter(|p|p.id==id).count();if count!=1{return Err("Choose one available Part.".into());}model.parts.retain(|p|p.id!=id);model.chapters.retain(|a|a.part_id!=id);Ok(())}
fn move_part(model:&mut ManuscriptParts,id:&str,delta:isize)->Result<(),String>{let index=model.parts.iter().position(|p|p.id==id).ok_or("Choose an available Part.")?;let target=index as isize+delta;if target<0||target>=model.parts.len() as isize{return Ok(());}model.parts.swap(index,target as usize);Ok(())}
fn assign(model:&mut ManuscriptParts,chapters:&[Chapter],chapter:&str,part:Option<&str>)->Result<(),String>{if !chapters.iter().any(|c|c.id==chapter){return Err("Choose a canonical chapter from the captured manuscript.".into());}if part.is_some_and(|id|!model.parts.iter().any(|p|p.id==id)){return Err("Choose an available Part or Ungrouped.".into());}model.chapters.retain(|a|a.chapter_id!=chapter);if let Some(part)=part{model.chapters.push(ChapterPart{chapter_id:chapter.into(),part_id:part.into()});}Ok(())}
/// Root may insert this label before a canonical chapter in outline/book. Walk
/// existing canonical chapter order; never sort chapters by the Parts array.
pub(crate) fn chapter_heading(model:&ManuscriptParts,chapter:&str)->Option<String>{let part=model.chapters.iter().find(|a|a.chapter_id==chapter).and_then(|a|model.parts.iter().find(|p|p.id==a.part_id))?;(!part.hidden).then(||part.title.clone())}
fn overview(model:&ManuscriptParts,chapters:&[Chapter],start:i64)->String{let mut text="Optional Parts · Part list order is separate from canonical chapter reading order. Hidden headings retain every chapter.\n\n".to_owned();let mut work=0;for part in &model.parts{if work>=2_000{break;}text.push_str(&format!("{}{}\n",part.title,if part.hidden{" · Heading hidden"}else{""}));for assignment in model.chapters.iter().filter(|a|a.part_id==part.id){work+=1;if work>2_000{break;}if let Some(chapter)=chapters.iter().find(|c|c.id==assignment.chapter_id){text.push_str(&format!("  Chapter {} · {}\n",chapter.position+start,chapter.title));}else{text.push_str("  Unavailable historical chapter assignment · preserved\n");}}text.push('\n');work+=1;}text.push_str("Ungrouped chapters\n");for chapter in chapters.iter().filter(|c|!model.chapters.iter().any(|a|a.chapter_id==c.id)){work+=1;if work>2_000{break;}text.push_str(&format!("  Chapter {} · {}\n",chapter.position+start,chapter.title));}if work>2_000{text.push_str("Parts overview limit reached; saved chapters and assignments are retained.\n");}text}

pub(super) struct PartsPage{
    pub widget:gtk::Box,pub dirty:Cell<bool>,pub saving:Cell<bool>,pub composing:Cell<bool>,pub loaded:Cell<bool>,pub status:gtk::Label,
    pub part:gtk::ComboBoxText,pub title:gtk::Entry,pub hidden:gtk::CheckButton,pub chapter:gtk::ComboBoxText,pub membership:gtk::ComboBoxText,
    project:String,controls:gtk::Box,snapshot:RefCell<Option<ManuscriptPartsSnapshot>>,draft:RefCell<ManuscriptParts>,updating:Cell<bool>,generation:Cell<u64>,overview:gtk::TextBuffer,
}
impl PartsPage{
    pub(super) fn new(project:String)->Rc<Self>{let widget=gtk::Box::new(gtk::Orientation::Vertical,10);widget.set_margin_start(32);widget.set_margin_end(32);widget.set_margin_top(24);let heading=gtk::Label::new(Some(crate::ui_text::text("page.organize_parts")));heading.set_xalign(0.);heading.style_context().add_class("page-title");widget.pack_start(&heading,false,false,0);let hint=gtk::Label::new(Some("Parts are optional named chapter groups. Part order and hidden headings do not move chapters or scenes. Removing a Part unassigns its chapters and retains all writing. Changes remain in this page until Save."));hint.set_line_wrap(true);hint.set_xalign(0.);widget.pack_start(&hint,false,false,0);let controls=gtk::Box::new(gtk::Orientation::Vertical,6);widget.pack_start(&controls,false,false,0);
        let part=gtk::ComboBoxText::new();part.set_tooltip_text(Some("Part to edit"));let title=gtk::Entry::new();title.set_placeholder_text(Some("Part title"));title.set_max_length(500);let hidden=gtk::CheckButton::with_label("Hide this heading; retain its chapters");for w in [part.clone().upcast::<gtk::Widget>(),title.clone().upcast(),hidden.clone().upcast()]{controls.pack_start(&w,false,false,0);}let actions=gtk::Box::new(gtk::Orientation::Horizontal,6);controls.pack_start(&actions,false,false,0);let add=gtk::Button::with_label("Add Part");let up=gtk::Button::with_label("Earlier in Part list");let down=gtk::Button::with_label("Later in Part list");let remove=gtk::Button::with_label("Remove Part and unassign chapters");for b in [&add,&up,&down,&remove]{actions.pack_start(b,false,false,0);}
        let chapter=gtk::ComboBoxText::new();chapter.set_tooltip_text(Some("Chapter to assign to Part"));let membership=gtk::ComboBoxText::new();membership.set_tooltip_text(Some("Chapter Part assignment"));controls.pack_start(&chapter,false,false,0);controls.pack_start(&membership,false,false,0);
        let status=gtk::Label::new(Some("Loading saved Parts and chapter sources…"));status.set_xalign(0.);status.set_line_wrap(true);widget.pack_start(&status,false,false,0);let view=gtk::TextView::new();view.set_editable(false);view.set_cursor_visible(false);view.set_wrap_mode(gtk::WrapMode::WordChar);widget.pack_start(&scroll(&view),true,true,0);
        let page=Rc::new(Self{widget,part,title,hidden,chapter,membership,status,controls,project,snapshot:RefCell::new(None),draft:RefCell::new(ManuscriptParts::default()),updating:Cell::new(false),generation:Cell::new(0),dirty:Cell::new(false),saving:Cell::new(false),composing:Cell::new(false),loaded:Cell::new(false),overview:view.buffer().unwrap()});
        let weak=Rc::downgrade(&page);page.part.connect_changed(move|_|if let Some(p)=weak.upgrade(){if !p.updating.get(){p.load_part_fields();}});let weak=Rc::downgrade(&page);page.chapter.connect_changed(move|_|if let Some(p)=weak.upgrade(){if !p.updating.get(){p.load_assignment();}});
        let weak=Rc::downgrade(&page);page.title.connect_changed(move|entry|if let Some(p)=weak.upgrade(){if p.can_edit(){let id=p.part.active_id().unwrap_or_default();let mut model=p.draft.borrow_mut();if let Some(part)=model.parts.iter_mut().find(|part|part.id==id.as_str()){part.title=entry.text().into();drop(model);p.changed();}}});let weak=Rc::downgrade(&page);page.title.connect_preedit_changed(move|_,text|if let Some(p)=weak.upgrade(){p.composing.set(!text.is_empty());});
        let weak=Rc::downgrade(&page);page.hidden.connect_toggled(move|check|if let Some(p)=weak.upgrade(){if p.can_edit(){let id=p.part.active_id().unwrap_or_default();let mut model=p.draft.borrow_mut();if let Some(part)=model.parts.iter_mut().find(|part|part.id==id.as_str()){part.hidden=check.is_active();drop(model);p.changed();}}});
        let weak=Rc::downgrade(&page);page.membership.connect_changed(move|combo|if let Some(p)=weak.upgrade(){if p.can_edit(){let Some(snapshot)=p.snapshot.borrow().clone()else{return;};let chapter=p.chapter.active_id().unwrap_or_default();let part=combo.active_id().unwrap_or_default();let result=assign(&mut p.draft.borrow_mut(),&snapshot.chapters,&chapter,(!part.is_empty()).then_some(part.as_str()));match result{Ok(())=>p.changed(),Err(error)=>p.status.set_text(&error)}}});
        let weak=Rc::downgrade(&page);add.connect_clicked(move|_|if let Some(p)=weak.upgrade(){if !p.can_edit()||p.composing.get(){return;}if p.draft.borrow().parts.len()>=1000{p.status.set_text("This manuscript reached its 1,000 Part limit.");return;}let id=uuid::Uuid::new_v4().to_string();p.draft.borrow_mut().parts.push(ManuscriptPart{id:id.clone(),title:"New Part".into(),hidden:false});p.changed();p.refresh_choices(Some(&id));});
        for (button,delta) in [(up,-1),(down,1)]{let weak=Rc::downgrade(&page);button.connect_clicked(move|_|if let Some(p)=weak.upgrade(){if !p.can_edit()||p.composing.get(){return;}let id=p.part.active_id().unwrap_or_default();let before=p.draft.borrow().clone();let result=move_part(&mut p.draft.borrow_mut(),&id,delta);match result{Ok(())=>{if *p.draft.borrow()!=before{p.changed();p.refresh_choices(Some(&id));}},Err(error)=>p.status.set_text(&error)}});}
        let weak=Rc::downgrade(&page);remove.connect_clicked(move|_|if let Some(p)=weak.upgrade(){if !p.can_edit()||p.composing.get(){return;}let id=p.part.active_id().unwrap_or_default();let result=remove_part(&mut p.draft.borrow_mut(),&id);match result{Ok(())=>{p.changed();p.refresh_choices(None);},Err(error)=>p.status.set_text(&error)}});
        let row=gtk::Box::new(gtk::Orientation::Horizontal,6);page.controls.pack_start(&row,false,false,0);let weak=Rc::downgrade(&page);button(&row,"Save Parts",move||if let Some(p)=weak.upgrade(){if let Some(owner)=desk::workspace_for_widget(p.widget.upcast_ref()){p.save(&owner,|_|{});}});let weak=Rc::downgrade(&page);button(&row,"Discard changes",move||if let Some(p)=weak.upgrade(){if !p.saving.get()&&!p.composing.get(){p.discard();}});page.controls.set_sensitive(false);page
    }
    fn owner(&self)->Option<Rc<Workspace>>{desk::workspace_for_widget(self.widget.upcast_ref()).filter(|owner|!owner.desk.is_closed()&&*owner.pid.borrow()==self.project)}
    fn can_edit(&self)->bool{self.loaded.get()&&!self.saving.get()&&!self.updating.get()&&self.owner().is_some_and(|owner|!owner.sequence_window_blocked())}
    fn changed(&self){if self.loaded.get(){let baseline=self.snapshot.borrow().as_ref().and_then(|s|s.planning.as_ref()).map(|p|ManuscriptParts::from_planning(&p.payload)).transpose().ok().flatten().unwrap_or_default();self.dirty.set(*self.draft.borrow()!=baseline);self.status.set_text(if self.dirty.get(){"Unsaved Parts draft · Save to keep it"}else{"Saved locally · Manual saving"});self.render();}}
    fn render(&self){if let Some(snapshot)=self.snapshot.borrow().as_ref(){self.overview.set_text(&overview(&self.draft.borrow(),&snapshot.chapters,snapshot.chapter_number_start));}}
    fn load_part_fields(&self){self.updating.set(true);let id=self.part.active_id().unwrap_or_default();let model=self.draft.borrow();let part=model.parts.iter().find(|p|p.id==id.as_str());self.title.set_text(part.map(|p|p.title.as_str()).unwrap_or(""));self.title.set_sensitive(part.is_some());self.hidden.set_sensitive(part.is_some());self.hidden.set_active(part.is_some_and(|p|p.hidden));self.updating.set(false);}
    fn load_assignment(&self){self.updating.set(true);let chapter=self.chapter.active_id().unwrap_or_default();let model=self.draft.borrow();let assigned=model.chapters.iter().find(|a|a.chapter_id==chapter.as_str()).map(|a|a.part_id.as_str()).unwrap_or("");self.membership.set_active_id(Some(assigned));self.updating.set(false);}
    fn refresh_choices(&self,selected:Option<&str>){self.updating.set(true);let old_chapter=self.chapter.active_id();let old_part=self.part.active_id();self.part.remove_all();self.membership.remove_all();self.chapter.remove_all();self.part.append(Some(""),"Choose Part");self.membership.append(Some(""),"Ungrouped");for part in &self.draft.borrow().parts{self.part.append(Some(&part.id),&part.title);self.membership.append(Some(&part.id),&part.title);}if let Some(snapshot)=self.snapshot.borrow().as_ref(){for chapter in &snapshot.chapters{self.chapter.append(Some(&chapter.id),&format!("{} · {}",chapter.position+snapshot.chapter_number_start,chapter.title));}}if !selected.or(old_part.as_deref()).is_some_and(|id|self.part.set_active_id(Some(id))){self.part.set_active(Some(0));}if !old_chapter.as_deref().is_some_and(|id|self.chapter.set_active_id(Some(id))){self.chapter.set_active(Some(0));}self.updating.set(false);self.load_part_fields();self.load_assignment();self.render();}
    fn restore(&self,snapshot:ManuscriptPartsSnapshot)->Result<(),String>{let model=snapshot.planning.as_ref().map(|p|ManuscriptParts::from_planning(&p.payload)).transpose()?.unwrap_or_default();*self.snapshot.borrow_mut()=Some(snapshot);*self.draft.borrow_mut()=model;self.loaded.set(true);self.dirty.set(false);self.refresh_choices(None);Ok(())}
    pub fn discard(&self){if self.saving.get()||self.composing.get()||self.owner().is_none_or(|owner|owner.sequence_window_blocked()){return;}let snapshot=self.snapshot.borrow().clone();if let Some(snapshot)=snapshot{if self.restore(snapshot).is_ok(){self.status.set_text("Parts changes discarded. Canonical chapters and writing retained.");}}}
    pub(super) fn load(self:&Rc<Self>,owner:&Rc<Workspace>,done:impl FnOnce()+'static){let generation=self.generation.get()+1;self.generation.set(generation);let p=self.clone();owner.client.rpc("parts_edit_snapshot",json!({"projectId":self.project}),move|reply|{if p.generation.get()!=generation||p.owner().is_none(){done();return;}match reply.and_then(|v|serde_json::from_value::<ManuscriptPartsSnapshot>(v).map_err(|_|"Unsupported saved Parts snapshot.".into())).and_then(|snapshot|{if snapshot.project_id!=p.project{return Err("Parts snapshot belongs to another manuscript.".into());}p.restore(snapshot)}){Ok(())=>{p.controls.set_sensitive(true);p.status.set_text("Saved locally · Manual saving");},Err(error)=>{p.loaded.set(false);p.controls.set_sensitive(false);p.status.set_text(&format!("Parts unavailable. {error}"));}}done();});}
    pub fn save(self:&Rc<Self>,owner:&Rc<Workspace>,done:impl FnOnce(Result<(),String>)+'static){let result=(||{if self.saving.get(){return Err("Parts are still saving.".to_owned());}if self.composing.get(){return Err("Finish entering the Part title before saving.".to_owned());}let actual=self.owner().ok_or("This Parts page is no longer owned by the selected manuscript window.")?;if actual.sequence_window_blocked(){return Err("Wait for the formatting sequence to finish before saving Parts.".into());}if !Rc::ptr_eq(owner,&actual){return Err("The Parts page moved to another window. Save from its current owner.".into());}if !self.dirty.get(){return Ok(None);}let snapshot=self.snapshot.borrow().clone().ok_or("Wait for saved Parts and chapter sources to load.")?;let model=self.draft.borrow().clone();model.validate()?;Ok(Some(json!({"snapshot":snapshot,"parts":model})))})();let args=match result{Ok(Some(args))=>args,Ok(None)=>{done(Ok(()));return;},Err(error)=>{self.status.set_text(&error);done(Err(error));return;}};self.saving.set(true);self.controls.set_sensitive(false);self.status.set_text("Saving checked Parts draft…");let p=self.clone();owner.client.rpc("save_manuscript_parts_checked",args,move|reply|{p.saving.set(false);let result=reply.and_then(|v|serde_json::from_value::<ManuscriptPartsSnapshot>(v).map_err(|_|"Saved Parts response could not be read. Draft retained; reload the confirmed revision before retrying.".into())).and_then(|snapshot|{if snapshot.project_id!=p.project{return Err("Saved Parts response belongs to another manuscript. Draft retained.".into());}p.restore(snapshot)});p.controls.set_sensitive(true);match &result{Ok(())=>{p.status.set_text("Saved locally · Canonical chapter and scene order unchanged");if let Some(owner)=p.owner(){owner.load_index();}},Err(error)=>p.status.set_text(&format!("Parts not saved; draft retained. {error}"))}done(result);});}
}
impl Workspace{pub(super) fn organize_parts(self:&Rc<Self>){let owner=desk::effective(self);let project=owner.pid.borrow().clone();if project.is_empty(){owner.error("Choose a manuscript before organizing Parts.");return;}let out=owner.clone();owner.navigate(move||{if out.desk.is_closed()||*out.pid.borrow()!=project{return;}let page=PartsPage::new(project);out.parts_pages.borrow_mut().push(page.clone());out.install(&page.widget,crate::ui_text::text("page.organize_parts"),true);page.load(&out,||{});});}}
